BEGIN;

ALTER TABLE llm_call_log
    ADD COLUMN IF NOT EXISTS wire_max_output_tokens  integer,
    ADD COLUMN IF NOT EXISTS thinking_reserve_tokens integer,
    ADD COLUMN IF NOT EXISTS thinking_tokens         integer,
    ADD COLUMN IF NOT EXISTS total_output_tokens     integer;

COMMENT ON COLUMN llm_call_log.thinking_tokens IS
    'Thinking tokens spent, from the provider''s usage metadata. BILLED AS OUTPUT but '
    'not answer, so deliberately not folded into output_tokens. This is where '
    'essentially all of Gemini''s cost lives. 0 is a real value; NULL means the '
    'provider did not report it.';

COMMIT;

-	WireMaxOutputTokens   interface{}
-	ThinkingReserveTokens interface{}
-	ThinkingTokens        interface{}
-	TotalOutputTokens     interface{}
+	// SEVEN LogLLMCall sites exist, not two. One map cannot be partially
+	// populated; four fields can, silently.
+	Options map[string]interface{}
 }
+
+// Read BEFORE the goroutine: the caller may reuse or mutate the map once
+// LogLLMCall returns, and this is explicitly fire-and-forget.
+wireMax, thinkReserve, thinkTokens, totalTokens := thinkingTelemetry(params.Options)
+
 go func() {

+func TestThinkingTelemetry_ReadsTheKeysGeminiActuallyWrites(t *testing.T) {
+	wire, reserve, thinking, total := thinkingTelemetry(map[string]interface{}{
+		"__sent_wire_max_output_tokens":  16192,
+		"__sent_thinking_reserve_tokens": 8192,
+		"__usage_thinking_tokens":        2878,
+		"__usage_total_tokens":           7105,
+	})
+	for _, c := range []struct {
+		name string
+		got  interface{}
+		want int
+	}{
+		{"wire_max_output_tokens", wire, 16192},
+		{"thinking_reserve_tokens", reserve, 8192},
+		{"thinking_tokens", thinking, 2878},
+		{"total_output_tokens", total, 7105},
+	} {
+		if v, ok := c.got.(int); !ok || v != c.want {
+			t.Errorf("%s: want %d, got %#v", c.name, c.want, c.got)
+		}
+	}
+}
+
+func TestLLMCallLogParams_OmittedOptionsYieldsAllNull(t *testing.T) {
+	p := LLMCallLogParams{Provider: "ollama"}
+	wire, reserve, thinking, total := thinkingTelemetry(p.Options)
+	if wire != nil || reserve != nil || thinking != nil || total != nil {
+		t.Fatalf("a site that passes no Options must log NULLs, got %#v %#v %#v %#v",
+			wire, reserve, thinking, total)
+	}
+}
